import json
import itertools
from hypothesis import strategies as st


def _alt_perms(n):
    res = []
    for p in itertools.permutations(range(1, n + 1)):
        if all((p[i] % 2) != (p[i + 1] % 2) for i in range(n - 1)):
            res.append(list(p))
    return res


@st.composite
def gen(draw):
    n = draw(st.integers(1, 7))
    cnt = len(_alt_perms(n))
    k = draw(st.one_of(
        st.integers(1, 5),
        st.integers(1, max(1, cnt)),
        st.integers(max(1, cnt - 2), cnt + 2),
        st.just(10**15),
    ))
    return f"{n}\n{k}\n"


def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    try:
        n, k = int(t[0]), int(t[1])
    except ValueError:
        return False
    return 1 <= n <= 100 and 1 <= k <= 10**15


def ref(inp):
    t = inp.split()
    n, k = int(t[0]), int(t[1])
    cands = _alt_perms(n)  # itertools.permutations of sorted input is lexicographic
    if 1 <= k <= len(cands):
        return json.dumps(cands[k - 1])
    return json.dumps([])
