import json
import itertools
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.one_of(st.integers(1, 3), st.integers(1, 7)))
    # Mix small k (in range) with huge k (usually out of range) and the extreme bound.
    k = draw(st.one_of(
        st.integers(1, 12),
        st.integers(1, 5040),
        st.just(10**15),
        st.integers(1, 10**15),
    ))
    return f"{n}\n{k}\n"

def validate(inp):
    lines = inp.strip().split("\n")
    if len(lines) != 2:
        return False
    try:
        n = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if type(n) is not int or type(k) is not int:
        return False
    return 1 <= n <= 100 and 1 <= k <= 10**15

def ref(inp):
    lines = inp.strip().split("\n")
    n = json.loads(lines[0])
    k = json.loads(lines[1])
    # itertools.permutations of a sorted list yields permutations in lexicographic order.
    count = 0
    for p in itertools.permutations(range(1, n + 1)):
        ok = True
        for i in range(n - 1):
            if (p[i] % 2) == (p[i + 1] % 2):
                ok = False
                break
        if ok:
            count += 1
            if count == k:
                return json.dumps(list(p))
    return json.dumps([])
