        st.just(1),
    ))
    return f"{n}\n{k}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 2:
        return False
    try:
        n, k = int(t[0]), int(t[1])
    except ValueError:
        return False
    return 1 <= n <= 100 and 1 <= k <= 10**15

def ref(inp):
    t = inp.split()
    n, k = int(t[0]), int(t[1])
    cnt = 0
    # permutations of sorted input are generated in lexicographic order
    for p in permutations(range(1, n + 1)):
        if all((p[i] - p[i + 1]) % 2 == 1 for i in range(n - 1)):
            cnt += 1
            if cnt == k:
